<?php $pagination = $pagination ?? ['page' => 1, 'pages' => 1, 'page_size' => 15, 'total' => 0]; $filters = $filters ?? []; $url = static function (int $page) use ($filters, $pagination): string { return current_url() . '?' . http_build_query(array_filter(['search' => $filters['search'] ?? '', 'action' => $filters['action'] ?? '', 'status' => $filters['status'] ?? '', 'from' => $filters['from'] ?? '', 'to' => $filters['to'] ?? '', 'page_size' => $pagination['page_size'] ?? 15, 'page' => $page], static fn ($value) => $value !== '' && $value !== null)); }; ?>
<div class="card-footer d-flex flex-wrap justify-content-between align-items-center"><span class="small text-muted">Page <?= esc((string) $pagination['page']) ?> of <?= esc((string) $pagination['pages']) ?> (<?= esc((string) $pagination['total']) ?> total)</span><nav aria-label="Farmassist audit pagination"><a class="btn btn-sm btn-outline-secondary" href="<?= $pagination['page'] > 1 ? esc($url($pagination['page'] - 1)) : '#' ?>" aria-label="Previous audit page">Previous</a> <a class="btn btn-sm btn-outline-secondary" href="<?= $pagination['page'] < $pagination['pages'] ? esc($url($pagination['page'] + 1)) : '#' ?>" aria-label="Next audit page">Next</a></nav></div>
